'use strict';
const $=s=>document.querySelector(s), app=$('#app');
const chapterNames=['Tổng quan về hành vi khách hàng','Các yếu tố bên ngoài','Các yếu tố tâm lý','Các yếu tố cá nhân','Quyết định mua của cá nhân','Hành vi mua của tổ chức','Quyết định mua của tổ chức'];
const chapterDescriptions=['Bắt đầu từ khách hàng, vai trò mua và cách nghiên cứu hành vi.','Văn hóa, nhóm tham khảo, gia đình và những tình huống tiêu dùng.','Đi từ nhu cầu, động cơ đến nhận thức, học hỏi và thái độ.','Tuổi, nghề nghiệp, quan niệm bản thân, lối sống và cá tính.','Theo dấu khách hàng từ nhận biết nhu cầu đến trải nghiệm sau mua.','Khám phá thị trường B2B và những nhân tố ảnh hưởng.','Các dạng mua, trung tâm mua và quy trình lựa chọn nhà cung cấp.'];
const ranges=[[4,30],[31,91],[92,169],[170,200],[201,246],[247,270],[271,301]];
let lessons=[],slides=[],questions=[],state={done:[],notes:{},cases:{},history:[],wrong:[]};
try{Object.assign(state,JSON.parse(localStorage.getItem('hvkh-study-v1')||'{}'))}catch{}
function save(){try{localStorage.setItem('hvkh-study-v1',JSON.stringify(state))}catch{toast('Không lưu được trên trình duyệt này. Hãy xuất tiến độ để giữ lại.')}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2200)}
const btn=(text,href,primary=false)=>`<a class="btn ${primary?'primary':''}" href="${href}">${text}</a>`;
function chapterCards(){return chapterNames.map((n,i)=>{const ls=lessons.filter(l=>l.ch===i+1),done=ls.filter(l=>state.done.includes(l.id)).length;return `<a class="card click" href="#chapter/${i+1}"><div class="card-top"><span class="card-number">0${i+1}</span><span class="badge">${done===ls.length?'Hoàn thành':done?'Đang học':'Sẵn sàng học'}</span></div><h3>${n}</h3><p>${chapterDescriptions[i]}</p><div class="bar"><i style="width:${done/ls.length*100}%"></i></div><div class="card-bottom"><span>${ls.length} bài học · Slide ${ranges[i].join('–')}</span><span>${done}/${ls.length} &nbsp; ↗</span></div></a>`}).join('')}
function stats(){return `<div class="stats"><div class="stat"><span class="stat-symbol">▤</span><div><strong>07</strong><small>Chương trong học phần</small></div></div><div class="stat"><span class="stat-symbol">▧</span><div><strong>37</strong><small>Bài học có giải thích</small></div></div><div class="stat"><span class="stat-symbol">✓</span><div><strong>42</strong><small>Câu hỏi có lời giải</small></div></div><div class="stat"><span class="stat-symbol">◷</span><div><strong>${Math.round(state.done.length/37*100)}<span style="font-size:14px">%</span></strong><small>${state.done.length}/37 bài đã đánh dấu học</small></div></div></div>`}
function home(){const next=lessons.find(l=>!state.done.includes(l.id))||lessons[0];app.innerHTML=`<div class="hero"><div class="hero-copy"><div class="eyebrow">HIỂU CON NGƯỜI · HIỂU LỰA CHỌN</div><h1>Mỗi quyết định mua<br>đều có một câu chuyện.</h1><p>Khám phá hành vi khách hàng qua lý thuyết, tình huống thực tế và những bài thực hành tương tác bám sát bài giảng của bạn.</p><div class="buttons">${btn(state.done.length?'Tiếp tục học &nbsp; →':'Bắt đầu chương đầu &nbsp; →','#lesson/'+next.id,true)}${btn('Khám phá thực hành','#labs')}</div></div><div class="hero-art" aria-label="Hành vi khách hàng chịu ảnh hưởng của văn hóa, xã hội, cá nhân và tâm lý"><div class="orbit"><div class="art-core">QUYẾT ĐỊNH<br>CỦA KHÁCH HÀNG</div><span class="art-label">Văn hóa</span><span class="art-label">Xã hội</span><span class="art-label">Cá nhân</span><span class="art-label">Tâm lý</span></div></div></div>${stats()}<div class="section-head"><div><h2>Lộ trình học tập của bạn</h2><p>7 chương · Đọc hiểu → Khám phá → Vận dụng → Tự kiểm tra</p></div><a class="link" href="#source">302 slide gốc ↗</a></div><div class="grid">${chapterCards()}</div><div class="section-head"><div><h2>Đưa kiến thức vào thực tế</h2><p>Thử thay đổi dữ kiện và giải thích điều gì xảy ra.</p></div></div><div class="lab-links"><a class="card click" href="#labs/supplier"><span class="eyebrow">B2B / SLIDE 287</span><h3>Ai là nhà cung cấp phù hợp?</h3><p>Thay trọng số, tính tổng điểm và kiểm tra thứ hạng A, B, C.</p><span class="link">Mở bảng đánh giá →</span></a><a class="card click" href="#labs/journey"><span class="eyebrow">HÀNH TRÌNH KHÁCH HÀNG</span><h3>Đi từ nhu cầu đến sau mua</h3><p>Bấm từng bước để thấy hành vi, dữ liệu và hành động marketing.</p><span class="link">Khám phá quy trình →</span></a><a class="card click" href="#cases"><span class="eyebrow">7 TÌNH HUỐNG / 7 CHƯƠNG</span><h3>Tập suy nghĩ như một marketer</h3><p>Viết phân tích, đối chiếu gợi ý và tự chấm bằng tiêu chí.</p><span class="link">Thực hành tình huống →</span></a></div><p class="note">Nguồn học phần: HÀNH VI KH-HK3-2026 – Full.pptx, 302 slide. Ví dụ, lời giải và bài thực hành được biên soạn thêm để hỗ trợ học; không phải đề thi chính thức. Tiến độ và ghi chú lưu trên trình duyệt bạn đang dùng.</p>`}
function chapter(c){const ls=lessons.filter(l=>l.ch===c);app.innerHTML=`<div class="eyebrow">HỌC PHẦN / CHƯƠNG 0${c}</div><h1>${chapterNames[c-1]}</h1><p class="intro">${chapterDescriptions[c-1]} Bắt đầu bằng bài học, kiểm tra ví dụ và đối chiếu với nguồn trước khi luyện tập.</p><div class="buttons">${btn('Luyện trắc nghiệm chương','#quiz/'+c,true)}${btn('Tình huống vận dụng','#cases/'+c)}${btn('Xem slide chương','#source/'+c)}</div><div class="two-col" style="margin-top:30px"><section class="panel"><div class="eyebrow">${ls.length} BÀI HỌC · SLIDE ${ranges[c-1].join('–')}</div>${ls.map((l,i)=>`<div class="lesson-row"><span class="row-num">${state.done.includes(l.id)?'✓':String(i+1).padStart(2,'0')}</span><div class="row-title"><h3>${l.title}</h3><small>Slide ${l.start}–${l.end} · ${l.core.length} ý chính · Ví dụ & điểm dễ nhầm</small></div>${btn('Học bài →','#lesson/'+l.id)}</div>`).join('')}</section><aside-content><div class="panel"><div class="eyebrow">MỤC TIÊU TỪ BÀI GIẢNG</div>${sourceText(ranges[c-1][0]+1)}${c===4?sourceText(172):''}</div><div class="callout"><strong>Học để giải thích được</strong>Với mỗi khái niệm, hãy trả lời: nó là gì, tác động bằng cách nào, dữ kiện nào chứng minh và ứng dụng marketing nào phù hợp?</div></aside-content></div>`}
function sourceText(n){const s=slides[n-1];return `<p style="white-space:pre-line;font-size:13px">${esc(s.text)}</p>`}
function sourceBlock(s){return `<details id="s${s.slide}"><summary><span class="badge">Slide ${s.slide}</span> &nbsp; ${esc(s.text.trim().split('\n').filter(Boolean)[0]?.slice(0,110)||'Hình minh họa trong bài giảng')}</summary><div class="slide-body"><pre>${esc(s.text)}</pre>${s.tables.map(t=>`<div class="table-wrap"><table>${t.map((r,i)=>`<tr>${r.map(c=>`<${i?'td':'th'}>${esc(c).replace(/\n/g,'<br>')}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</table></div>`).join('')}${s.images.map(p=>`<img loading="lazy" src="${p}" alt="Hình từ slide ${s.slide}">`).join('')}${!s.text.trim()&&!s.images.length?'<p class="note">Trang chứa sơ đồ hoặc đối tượng đồ họa. Xem bố cục nguyên bản trong PowerPoint.</p>':''}</div></details>`}
function lesson(id){const l=lessons[id];if(!l)return home();const done=state.done.includes(id);app.innerHTML=`<a class="link" href="#chapter/${l.ch}">← Chương ${l.ch}: ${chapterNames[l.ch-1]}</a><h1>${l.title}</h1><div class="tag-row"><span class="badge">Bài ${id+1} / 37</span><span class="badge">Slide ${l.start}–${l.end}</span><span class="badge">CLO1 · CLO2 · CLO3</span></div><div class="tabs"><button data-tab="read" class="active">Hiểu lý thuyết</button><button data-tab="original">Đối chiếu slide</button><button data-tab="notes">Ghi chú của tôi</button></div><div id="lesson-body"></div><div class="buttons"><button class="btn primary" id="complete">${done?'✓ Đã học bài này':'Đánh dấu đã học'}</button>${id?btn('← Bài trước','#lesson/'+(id-1)):''}${id<36?btn('Bài tiếp theo →','#lesson/'+(id+1)):btn('Ôn toàn học phần','#quiz')}</div>`;const render=t=>{$('#lesson-body').innerHTML=t==='original'?`<p class="note">Nội dung văn bản, bảng và ảnh trích từ nguồn; sơ đồ vẽ bằng các đối tượng PowerPoint cần đối chiếu bố cục nguyên bản. <a class="link" href="bai-giang-goc.pptx" download>Tải bài giảng gốc</a></p>${slides.filter(s=>s.slide>=l.start&&s.slide<=l.end).map(sourceBlock).join('')}`:t==='notes'?`<div class="panel"><h2>Viết lại bằng lời của bạn</h2><p class="note">Gợi ý: định nghĩa → cơ chế → ví dụ → ứng dụng. Ghi chú tự lưu trên trình duyệt.</p><textarea id="notes" aria-label="Ghi chú bài học" placeholder="Mình hiểu khái niệm này là…">${esc(state.notes[id]||'')}</textarea><div class="buttons"><button class="btn" onclick="window.print()">In bài / lưu PDF</button></div></div>`:`<div class="two-col"><section class="panel"><div class="eyebrow">DIỄN GIẢI HỖ TRỢ HỌC TẬP</div>${l.core.map((p,i)=>`<div class="concept"><span class="eyebrow">Ý CHÍNH 0${i+1}</span><p>${esc(p)}</p></div>`).join('')}<div class="callout"><strong>THỬ NHÌN QUA MỘT VÍ DỤ</strong>${esc(l.example)}</div><div class="callout warning"><strong>ĐIỂM DỄ NHẦM</strong>${esc(l.trap)}</div></section><div><div class="panel"><div class="eyebrow">CHỦ ĐỘNG NHỚ LẠI</div><h3>Đừng vội lật lại bài.</h3><p class="note">Giải thích chủ đề này cho một người chưa học. Nêu một ví dụ khác với ví dụ trong bài.</p><textarea aria-label="Câu trả lời tự kiểm tra" id="recall" placeholder="Khái niệm chính là…\nVí dụ của mình…"></textarea><details><summary>Kiểm tra câu trả lời bằng 3 bước</summary><div class="slide-body"><p>1. Có nêu đúng khái niệm và phân biệt điểm dễ nhầm?</p><p>2. Có chỉ ra dữ kiện và cơ chế tác động trong ví dụ?</p><p>3. Có nêu ứng dụng phù hợp mà không khẳng định quá mức?</p><p class="note">Đây là khung tự đối chiếu, không phải chấm điểm tự động.</p></div></details>${btn('Luyện câu hỏi chương →','#quiz/'+l.ch,true)}</div><div class="callout"><strong>NGUỒN ĐỐI CHIẾU</strong>Slide ${l.start}–${l.end}. Bài giải thích và ví dụ là nội dung biên soạn thêm; dùng tab “Đối chiếu slide” khi cần kiểm tra cách gọi trong môn.</div></div></div>`;if(t==='notes')$('#notes').oninput=e=>{state.notes[id]=e.target.value;save()}};render('read');document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));render(b.dataset.tab)});$('#complete').onclick=()=>{if(state.done.includes(id))state.done=state.done.filter(x=>x!==id);else state.done.push(id);save();lesson(id);toast(state.done.includes(id)?'Đã lưu tiến độ bài học':'Đã bỏ đánh dấu bài học')};}
let quizState=null;
function quiz(c){const errors=state.wrong.length;app.innerHTML=`<div class="eyebrow">LUYỆN TẬP CHỦ ĐỘNG</div><h1>Hiểu chắc hơn sau mỗi câu hỏi.</h1><p class="intro">42 câu biên soạn theo 7 chương. Mỗi câu có đáp án, giải thích và số slide đối chiếu. Bộ đề tự luyện không mô phỏng một cấu trúc thi chưa được cung cấp.</p><div class="two-col"><div class="panel"><h2>Thiết lập phiên học</h2><p><label for="quiz-ch">Phạm vi</label></p><select id="quiz-ch"><option value="0">Toàn bộ 7 chương</option>${chapterNames.map((n,i)=>`<option value="${i+1}" ${c===i+1?'selected':''}>Chương ${i+1} · ${n}</option>`).join('')}<option value="wrong">Câu từng trả lời sai (${errors})</option></select><p><label for="quiz-mode">Cách luyện</label></p><select id="quiz-mode"><option value="learn">Luyện tập · xem giải thích từng câu</option><option value="exam">Tự kiểm tra · xem lời giải sau khi nộp</option></select><div class="buttons"><button class="btn primary" id="startquiz">Bắt đầu luyện →</button></div><div id="quiznotice"></div></div><div class="panel"><div class="eyebrow">NHỚ THEO CÁCH CỦA BẠN</div><h3>Flashcard khái niệm</h3><p class="muted">37 thẻ từ các bài học. Tự trả lời trước khi lật, đánh dấu thẻ cần ôn và quay lại khi sẵn sàng.</p>${btn('Mở flashcard','#flash')}</div></div>`;$('#startquiz').onclick=()=>{let ch=$('#quiz-ch').value,mode=$('#quiz-mode').value;const pool=questions.map((q,i)=>({...q,id:i})).filter(q=>ch==='wrong'?state.wrong.includes(q.id):+ch===0||q.ch===+ch);if(!pool.length){$('#quiznotice').innerHTML='<p>Chưa có câu sai để ôn. Hãy bắt đầu một phiên luyện tập.</p>';return}for(let i=pool.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}quizState={pool,mode,index:0,answers:{},revealed:{},start:Date.now()};quizQuestion()}}
function quizQuestion(){const z=quizState,q=z.pool[z.index],ans=z.answers[q.id],revealed=z.revealed[q.id];app.innerHTML=`<a class="link" href="#quiz" onclick="event.preventDefault();quiz()">← Thiết lập luyện tập</a><div class="quiz-count">${z.mode==='learn'?'LUYỆN TẬP':'TỰ KIỂM TRA'} · Câu ${z.index+1} / ${z.pool.length} · Chương ${q.ch}</div><div class="bar"><i style="width:${(z.index+1)/z.pool.length*100}%"></i></div><div class="panel"><h2>${esc(q.q)}</h2>${q.options.map((o,i)=>`<button class="option ${ans===i?'selected':''} ${revealed?(i===q.answer?'correct':i===ans?'wrong':''):''}" data-answer="${i}" ${revealed?'disabled':''}>${'ABCD'[i]}. ${esc(o)}</button>`).join('')}${revealed?`<div class="explanation"><strong>${ans===q.answer?'✓ Chính xác':'Cần xem lại'} · Đáp án ${'ABCD'[q.answer]}</strong><p>${q.explain}</p><a class="link" href="#source/slide/${q.slide}">Đối chiếu slide ${q.slide} ↗</a></div>`:''}<div class="buttons">${z.index?'<button class="btn" id="qprev">← Câu trước</button>':''}${z.mode==='learn'&&!revealed?'<button class="btn primary" id="check">Kiểm tra đáp án</button>':''}<button class="btn ${z.mode==='exam'||revealed?'primary':''}" id="qnext">${z.index===z.pool.length-1?'Nộp bài và xem kết quả':'Câu tiếp →'}</button></div><p id="qnotice" class="note"></p></div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{z.answers[q.id]=+b.dataset.answer;quizQuestion()});if($('#check'))$('#check').onclick=()=>{if(ans===undefined){$('#qnotice').textContent='Hãy chọn một đáp án trước khi kiểm tra.';return}z.revealed[q.id]=true;quizQuestion()};if($('#qprev'))$('#qprev').onclick=()=>{z.index--;quizQuestion()};$('#qnext').onclick=()=>{if(ans===undefined){$('#qnotice').textContent='Hãy chọn một đáp án trước khi tiếp tục.';return}if(z.mode==='learn'&&!revealed){$('#qnotice').textContent='Bấm “Kiểm tra đáp án” để xem lời giải trước.';return}if(z.index<z.pool.length-1){z.index++;quizQuestion()}else quizResult()}}
function quizResult(){const z=quizState,correct=z.pool.filter(q=>z.answers[q.id]===q.answer).length;z.pool.forEach(q=>{if(z.answers[q.id]!==q.answer){if(!state.wrong.includes(q.id))state.wrong.push(q.id)}else state.wrong=state.wrong.filter(x=>x!==q.id)});state.history.unshift({date:new Date().toISOString(),correct,total:z.pool.length,seconds:Math.round((Date.now()-z.start)/1000),mode:z.mode});state.history=state.history.slice(0,40);save();app.innerHTML=`<div class="eyebrow">ĐÃ HOÀN THÀNH PHIÊN HỌC</div><h1>Kết quả tự kiểm tra</h1><div class="panel center"><div class="score">${correct}<span style="font-size:25px"> / ${z.pool.length}</span></div><p>${Math.round(correct/z.pool.length*100)}% chính xác · ${Math.round((Date.now()-z.start)/60000)} phút</p><div class="buttons" style="justify-content:center"><button class="btn primary" onclick="quiz()">Luyện lại</button>${btn('Xem tiến độ','#progress')}</div></div><h2>Đối chiếu từng câu</h2>${z.pool.map(q=>`<details><summary>${z.answers[q.id]===q.answer?'✓':'○'} ${esc(q.q)}</summary><div class="slide-body"><p>Bạn chọn: ${'ABCD'[z.answers[q.id]]}. ${esc(q.options[z.answers[q.id]])}</p><strong>Đáp án ${'ABCD'[q.answer]}. ${esc(q.options[q.answer])}</strong><p>${q.explain}</p><a class="link" href="#source/slide/${q.slide}">Slide ${q.slide}</a></div></details>`).join('')}`}
let flashIds=[],flashIndex=0,flipped=false,flashFilter=0;
function flash(reset=true){if(reset){flashFilter=0;flashIds=lessons.map(l=>l.id);flashIndex=0;flipped=false}const l=lessons[flashIds[flashIndex]];app.innerHTML=`<div class="eyebrow">ÔN NHỚ / FLASHCARD</div><h1>Nhớ bằng cách tự giải thích.</h1><div class="section-head"><span class="muted">Thẻ ${flashIndex+1} / ${flashIds.length} · Chương ${l.ch}</span><select id="flashfilter" aria-label="Lọc flashcard"><option value="0">Tất cả chương</option>${chapterNames.map((_,i)=>`<option value="${i+1}">Chương ${i+1}</option>`).join('')}</select></div><button class="flash" id="flip"><small>${flipped?'ĐỐI CHIẾU CÂU TRẢ LỜI':'HÃY GIẢI THÍCH CHỦ ĐỀ NÀY · BẤM ĐỂ LẬT'}</small>${flipped?`<div class="answer">${esc(l.core[0])}</div>`:esc(l.title)}</button><div class="buttons"><button class="btn" id="fprev">← Thẻ trước</button><button class="btn primary" id="fnext">Đã nhớ · tiếp →</button><button class="btn" id="fagain">Cần ôn lại</button>${btn('Đọc bài đầy đủ','#lesson/'+l.id)}</div><p class="note">“Cần ôn lại” chuyển thẻ hiện tại xuống cuối lượt. Flashcard hỗ trợ tự đánh giá, không tự động chứng nhận đã nắm vững bài.</p>`;$('#flip').onclick=()=>{flipped=!flipped;flash(false)};$('#fnext').onclick=()=>{flashIndex=(flashIndex+1)%flashIds.length;flipped=false;flash(false)};$('#fprev').onclick=()=>{flashIndex=(flashIndex-1+flashIds.length)%flashIds.length;flipped=false;flash(false)};$('#fagain').onclick=()=>{const id=flashIds.splice(flashIndex,1)[0];flashIds.push(id);flashIndex=Math.min(flashIndex,flashIds.length-1);flipped=false;flash(false);toast('Đã chuyển thẻ xuống cuối lượt')};$('#flashfilter').value=String(flashFilter);$('#flashfilter').onchange=e=>{flashFilter=+e.target.value;flashIds=lessons.filter(l=>!+e.target.value||l.ch===+e.target.value).map(l=>l.id);flashIndex=0;flipped=false;flash(false)}}
const caseData=[
['Ai thực sự là khách hàng?','Một cửa hàng bán bộ đồ học tập: phụ huynh thanh toán, học sinh dùng, giáo viên gợi ý nhãn hiệu. Doanh số giảm dù nhiều phụ huynh biết đến cửa hàng.','Phân biệt vai trò mua, dùng và ảnh hưởng. Nêu 2 giả thuyết cho doanh số giảm, chọn phương pháp kiểm tra, đề xuất điều chỉnh marketing.','Phụ huynh là người mua; học sinh là người dùng; giáo viên có thể là người ảnh hưởng. Chưa đủ dữ liệu kết luận vì sao doanh số giảm. Có thể kiểm tra rào cản giá bằng khảo sát và kiểm tra trải nghiệm sản phẩm qua quan sát/phỏng vấn. Tách giả thuyết khỏi kết luận, dùng thực nghiệm khi muốn kiểm tra tác động thay đổi cụ thể.','Xác định đúng ít nhất 3 vai trò|Hai giả thuyết có thể kiểm tra|Phương pháp gắn câu hỏi nghiên cứu|Giải pháp 4P gắn với phát hiện'],
['Chiến dịch quà Tết cho sinh viên','Một thương hiệu định bán quà Tết cho sinh viên xa nhà. Khách quan tâm giá, sự phù hợp để biếu người lớn và việc bạn bè đánh giá món quà. Những ngày gần Tết, thời gian giao hàng trở thành mối lo chính.','Phân tích văn hóa, xã hội và tình huống. Đề xuất thông điệp, kênh và dịch vụ phù hợp; tránh quy chụp mọi sinh viên giống nhau.','Kính trọng gia đình là giá trị văn hóa; bạn bè là nhóm tham khảo; thời gian gấp và giao hàng là tình huống. Có thể dùng thông điệp tri ân, thông tin lựa chọn quà phù hợp và cam kết giao hàng thực tế. Phân khúc thêm theo ngân sách, nơi nhận và thời điểm đặt; không dùng lời hứa vượt khả năng vận hành.','Phân biệt đúng 3 nhóm yếu tố|Chỉ ra cơ chế tác động của từng yếu tố|Đề xuất thông điệp và dịch vụ nhất quán|Nêu giới hạn dữ liệu và khác biệt trong nhóm'],
['Thích thương hiệu, nhưng chưa mua','Một sinh viên thích xe điện A, tin rằng tiết kiệm nhưng gia đình lo pin, ngân sách chưa đủ và điểm sạc gần nhà ít. Quảng cáo mới tiếp tục nhấn mạnh rằng A rất phong cách.','Phân tích nhận thức, cảm xúc, ý định và rào cản. Vận dụng TPB để đề xuất 3 thay đổi, thay vì chỉ tăng quảng cáo hình ảnh.','Niềm tin tiết kiệm thuộc nhận thức; thích thuộc cảm xúc. Ý kiến gia đình gắn chuẩn chủ quan; tiền và điểm sạc gắn khả năng kiểm soát được cảm nhận và điều kiện thực tế. Cần thông tin pin có bằng chứng, phương án chi trả minh bạch và cải thiện khả năng sạc. Thái độ tích cực chưa đủ để mua.','Phân biệt ba thành phần/ý định/hành vi|Áp dụng đúng thái độ, chuẩn chủ quan, kiểm soát|Ba giải pháp xử lý đúng rào cản|Không suy diễn quảng cáo sẽ tự bảo đảm mua'],
['Hai khách hàng cùng tuổi, hai lựa chọn','Lan và Minh đều 28 tuổi, thu nhập tương đương. Lan có con nhỏ và cần chiếc xe an toàn, tiết kiệm. Minh sống một mình, thích trải nghiệm và muốn chiếc xe thể hiện cá tính.','Phân tích vòng đời gia đình, lối sống và quan niệm bản thân. Đề xuất hai định vị sản phẩm, kèm dữ liệu cần thu thập để kiểm chứng.','Lan có thể ưu tiên nhu cầu gia đình; Minh thể hiện lối sống khám phá và hình ảnh bản thân mong muốn. Định vị có thể nhấn an toàn/chi phí sử dụng cho Lan và trải nghiệm/thiết kế cho Minh, nhưng vẫn phải xác minh tiêu chí và mức đánh đổi thực tế. Cùng tuổi/thu nhập chưa đủ kết luận cùng nhu cầu.','Giải thích vòng đời gia đình|Phân biệt lối sống và quan niệm bản thân|Hai định vị có căn cứ dữ kiện|Nêu cách kiểm chứng thay vì gắn nhãn'],
['Hành trình mua laptop đầu tiên','Một bạn cần laptop làm đồ án, hỏi bạn bè, xem video, so sánh 3 mẫu rồi chọn B. Đến cửa hàng B hết hàng; nhân viên đề nghị C. Sau mua C, bạn thấy một video chê sản phẩm và bắt đầu bất an.','Xác định các giai đoạn và nguồn thông tin. Phân tích sự thay đổi quyết định, sau đó đề xuất cách chăm sóc sau mua.','Nhu cầu làm đồ án kích hoạt vấn đề; bạn bè/video là nguồn bên ngoài; so 3 mẫu là đánh giá. Hết hàng là hoàn cảnh xen giữa ý định và mua. Sau mua cần hỗ trợ sử dụng, đối chiếu tiêu chí đúng nhu cầu, tiếp nhận phản hồi và xử lý lỗi thực; tránh chỉ trấn an chung chung.','Xác định đúng 5 giai đoạn|Phân loại đúng nguồn thông tin|Giải thích tác động hết hàng|Đề xuất hỗ trợ sau mua có nội dung cụ thể'],
['Nhà máy lựa chọn vật liệu mới','Đơn hàng khách cuối tăng, nhà máy cần thêm nguyên liệu. Chính sách yêu cầu 3 báo giá. Trưởng kỹ thuật ưu tiên độ ổn định; giám đốc tài chính muốn giảm chi phí; người phụ trách mua ngại đổi nhà cung cấp vì từng gặp lỗi giao hàng.','Áp dụng mô hình B2B và bốn nhóm nhân tố. Chỉ ra ai tham gia, dữ liệu nào cần xác minh và nhà cung cấp nên tiếp cận ra sao.','Nhu cầu đơn hàng cuối là cầu thứ phát và yếu tố thị trường; quy định 3 báo giá thuộc tổ chức; khác ưu tiên kỹ thuật/tài chính tạo tương tác cần thống nhất; kinh nghiệm và thái độ rủi ro của người mua là cá nhân. Đề xuất dữ liệu chất lượng, tổng chi phí và độ đúng hạn để từng vai trò đánh giá.','Giải thích cầu thứ phát|Phân biệt 4 cấp độ nhân tố|Xác định vai trò và tiêu chí khác nhau|Đề xuất bằng chứng phù hợp từng người'],
['Đơn hàng giá rẻ nhưng giao trễ','Nhà máy chạy JIT so sánh nhà cung cấp A giá thấp nhưng giao trễ, B giá cao hơn nhưng ổn định. Bảng chấm điểm tổng cho B nhỉnh hơn. Ban giám đốc hỏi liệu chỉ nhìn tổng điểm có đủ không.','Vận dụng giá trị, tổng chi phí, JIT và tiêu chí bắt buộc. Đề xuất cách chọn, giám sát và xử lý rủi ro; liên hệ ba dạng mua.','Phải xét chi phí dừng chuyền, tồn kho, kiểm định và lỗi giao hàng, không chỉ giá mua. Điểm tổng chỉ hỗ trợ; điều kiện kỹ thuật/pháp lý bắt buộc phải được đáp ứng. Với JIT, độ tin cậy giao hàng quan trọng. Cần thỏa thuận chỉ số chất lượng/đúng hạn và phương án dự phòng; thay điều kiện hợp đồng cũ là mua lặp lại có điều chỉnh.','Xét lợi ích và tổng chi phí|Nêu điều kiện bắt buộc trước chấm điểm|Phân tích lợi ích/rủi ro JIT|Đề xuất theo dõi và dự phòng cụ thể']
];
function cases(c){if(!c){app.innerHTML=`<div class="eyebrow">VẬN DỤNG / TỰ LUẬN</div><h1>Đặt kiến thức vào một quyết định thật.</h1><p class="intro">7 tình huống biên soạn thêm, mỗi chương một bài. Viết câu trả lời trước, sau đó mở gợi ý và tự chấm theo tiêu chí. Nội dung tự lưu trên trình duyệt.</p><div class="grid">${caseData.map((x,i)=>`<a class="card click" href="#cases/${i+1}"><span class="badge">Chương ${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p><span class="link">Phân tích tình huống →</span></a>`).join('')}</div>`;return}const d=caseData[c-1];app.innerHTML=`<a class="link" href="#cases">← Tất cả tình huống</a><h1>${d[0]}</h1><div class="two-col"><div class="panel"><span class="badge">Chương ${c} · CLO2 & CLO3</span><p>${d[1]}</p><div class="callout"><strong>NHIỆM VỤ</strong>${d[2]}</div><label for="case-answer"><h3>Bài phân tích của bạn</h3></label><textarea id="case-answer" style="min-height:280px" placeholder="Dữ kiện → khái niệm → cơ chế → giải pháp → cách kiểm tra…">${esc(state.cases[c]||'')}</textarea><div class="buttons"><button class="btn" onclick="window.print()">In phiếu thực hành</button>${btn('Ôn lý thuyết','#chapter/'+c)}</div></div><div><details><summary>Mở gợi ý sau khi tự làm</summary><div class="slide-body"><p>${d[3]}</p><p class="note">Gợi ý có nhiều cách triển khai; không phải đáp án duy nhất.</p></div></details><div class="panel"><h3>Tự chấm theo tiêu chí</h3><p class="note">Mỗi tiêu chí: 0 chưa có · 1 có nhưng chưa rõ · 2 rõ và có căn cứ. Đây là tự đánh giá, không chấm tự động nội dung bài viết.</p>${d[4].split('|').map((r,i)=>`<label style="display:block;margin:18px 0;font-size:13px">${r}<select class="rubric" aria-label="Điểm tiêu chí ${i+1}" style="float:right"><option>0</option><option>1</option><option>2</option></select></label>`).join('')}<div id="rubric-total" class="feedback">Tự đánh giá: 0 / 8 điểm</div></div></div></div>`;$('#case-answer').oninput=e=>{state.cases[c]=e.target.value;save()};document.querySelectorAll('.rubric').forEach(s=>s.onchange=()=>{$('#rubric-total').textContent='Tự đánh giá: '+[...document.querySelectorAll('.rubric')].reduce((n,x)=>n+(+x.value),0)+' / 8 điểm'})}
const journey=[['Nhận biết nhu cầu','Laptop hiện tại không chạy được phần mềm đồ án.','Đâu là khoảng cách giữa thực tế và mong muốn?','Nghiên cứu vấn đề, trình bày lợi ích đúng nhu cầu.'],['Tìm kiếm thông tin','Nhớ lần dùng cũ, hỏi bạn, xem review và thử sản phẩm.','Nguồn nội bộ hay bên ngoài? Độ tin cậy thế nào?','Cung cấp đặc tính rõ, demo và nguồn thông tin đáng kiểm tra.'],['Đánh giá lựa chọn','So hiệu năng, pin, giá, trọng lượng và hình ảnh thương hiệu.','Thuộc tính nào quan trọng nhất với người này?','Chứng minh ưu thế liên quan nhu cầu, hỗ trợ so sánh minh bạch.'],['Quyết định mua','Chọn mẫu, cửa hàng, thời gian và cách thanh toán.','Có rào cản ngân sách, tồn kho hay ý kiến người khác?','Giữ thông tin tồn kho, giao nhận, thanh toán rõ ràng.'],['Sau mua','Sử dụng, đánh giá hài lòng, phản hồi hoặc giới thiệu.','Trải nghiệm có phù hợp kỳ vọng và có vấn đề cần xử lý?','Hướng dẫn sử dụng, hỗ trợ, tiếp nhận phản hồi và cải tiến.']];
const b2bSteps=['Nhận thức vấn đề','Phác họa tổng quát nhu cầu','Chi tiết kỹ thuật','Tìm kiếm nhà cung cấp','Yêu cầu chào hàng','Lựa chọn nhà cung cấp','Đặt hàng','Đánh giá kết quả'];
const b2bExamples=['Dây chuyền cũ hỏng, phát sinh nhu cầu thay thế.','Xác định năng lực cần có và số lượng máy.','Kỹ sư đặt yêu cầu công suất, tương thích và chất lượng.','Tìm ứng viên qua hội chợ, Internet và giới thiệu.','Mời ứng viên gửi đề xuất kỹ thuật, giá và hỗ trợ.','Đối chiếu điều kiện bắt buộc và chấm tiêu chí.','Thống nhất số lượng, giá, chất lượng, giao hàng và thanh toán.','Đo chất lượng, đúng hạn, chi phí phát sinh và phản hồi người dùng.'];
function labs(type){app.innerHTML=`<div class="eyebrow">PHÒNG THỰC HÀNH TƯƠNG TÁC</div><h1>Thử thay đổi. Quan sát. Giải thích.</h1><p class="intro">Các công cụ minh họa giúp vận dụng khái niệm trong bài giảng. Dữ liệu giả định được ghi rõ; bảng nhà cung cấp dùng đúng số liệu slide 287.</p><div class="tabs">${[['journey','Hành trình cá nhân'],['b2b','8 bước mua tổ chức'],['supplier','Chấm nhà cung cấp'],['perception','Ngưỡng vi sai'],['classify','Phân loại tình huống']].map(([k,v])=>`<button data-lab="${k}" class="${(type||'journey')===k?'active':''}">${v}</button>`).join('')}</div><div id="lab-content"></div>`;document.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>location.hash='labs/'+b.dataset.lab);if(type==='supplier')supplier();else if(type==='perception')perception();else if(type==='classify')classify();else if(type==='b2b')processB2B();else processJourney()}
function processJourney(){const box=$('#lab-content');box.innerHTML=`<div class="panel"><h2>5 giai đoạn ra quyết định mua cá nhân</h2><p class="note">Bấm từng bước. Quy trình thực tế có thể rút gọn, lặp lại hoặc dừng lại tùy mức tham gia.</p><div class="process">${journey.map((x,i)=>`<button data-step="${i}"><b>0${i+1}</b>${x[0]}</button>`).join('')}</div><div id="step-detail"></div></div><div class="callout"><strong>THỬ TỰ TRẢ LỜI</strong>Khi khách đã chọn B nhưng B hết hàng, biến cố xảy ra ở bước nào? Tồn kho tác động ra sao đến khoảng cách giữa ý định và mua?<details><summary>Xem phân tích</summary><div class="slide-body">Biến cố xen vào quyết định mua. Nó có thể làm khách chờ, chuyển cửa hàng, đổi thương hiệu hoặc hoãn mua. Đây là tình huống, không tự chứng minh khách có thái độ tiêu cực với B.</div></details></div>`;const show=i=>{document.querySelectorAll('[data-step]').forEach(b=>b.classList.toggle('active',+b.dataset.step===i));const x=journey[i];$('#step-detail').innerHTML=`<div class="two-col"><div class="callout"><strong>KHÁCH HÀNG ĐANG LÀM GÌ?</strong>${x[1]}</div><div class="callout"><strong>CÂU HỎI NGHIÊN CỨU</strong>${x[2]}</div></div><h3>Hàm ý marketing</h3><p>${x[3]}</p><a class="link" href="#source/5">Nguồn: chương 5, slide 225–241</a>`};document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>show(+b.dataset.step));show(0)}
function processB2B(){const box=$('#lab-content');box.innerHTML=`<div class="panel"><h2>8 bước mua của tổ chức</h2><p class="note">Ví dụ minh họa: nhà máy mua máy mới. Bấm một giai đoạn để thấy nhiệm vụ cụ thể.</p><div class="process">${b2bSteps.map((x,i)=>`<button data-bstep="${i}"><b>0${i+1}</b>${x}</button>`).join('')}</div><div id="bstep"></div></div><div class="panel"><h3>Thực hành thứ tự: sau bước này là gì?</h3><p id="order-question"></p><div id="order-options"></div><div id="order-feedback"></div><button class="btn" id="order-new">Tình huống tiếp theo</button></div>`;const show=i=>{document.querySelectorAll('[data-bstep]').forEach(b=>b.classList.toggle('active',+b.dataset.bstep===i));$('#bstep').innerHTML=`<div class="callout"><strong>${i+1}. ${b2bSteps[i]}</strong>${b2bExamples[i]}</div><a class="link" href="#source/slide/284">Đối chiếu slide 284–288</a>`};document.querySelectorAll('[data-bstep]').forEach(b=>b.onclick=()=>show(+b.dataset.bstep));show(0);let n=0;const order=()=>{n=Math.floor(Math.random()*7);$('#order-question').textContent=`Sau “${b2bSteps[n]}”, bước kế tiếp là gì?`;$('#order-feedback').innerHTML='';$('#order-options').innerHTML=b2bSteps.map((x,i)=>`<button class="option" data-order="${i}">${x}</button>`).join('');document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{$('#order-feedback').innerHTML=`<p class="feedback">${+b.dataset.order===n+1?'✓ Đúng.':'Cần xem lại.'} Bước kế tiếp: ${b2bSteps[n+1]}. ${b2bExamples[n+1]}</p>`})};$('#order-new').onclick=order;order()}
function supplier(){const names=['Hiệu suất','Kinh tế','Thích hợp','Thích nghi','Pháp lý'],weights=[4,5,1,2,3],scores=[[3,4,2],[4,4,3],[3,5,5],[1,3,3],[4,3,1]];$('#lab-content').innerHTML=`<div class="panel"><h2>Bảng lựa chọn nhà cung cấp</h2><p class="note">Khởi tạo đúng bảng slide 287. Điểm từ 1–5; trọng số 0–10. Điểm tổng = Σ(trọng số × điểm). Thử tăng trọng số “pháp lý” và quan sát sự thay đổi.</p><div class="table-wrap"><table><thead><tr><th>Tiêu chí</th><th>Trọng số</th><th>A</th><th>B</th><th>C</th></tr></thead><tbody>${names.map((n,i)=>`<tr><td>${n}</td><td><input type="number" aria-label="Trọng số ${n}" min="0" max="10" value="${weights[i]}" class="weight" data-i="${i}"></td>${scores[i].map((s,j)=>`<td><input type="number" aria-label="Điểm ${n} nhà cung cấp ${'ABC'[j]}" min="1" max="5" value="${s}" class="supplier-score" data-i="${i}" data-j="${j}"></td>`).join('')}</tr>`).join('')}</tbody><tfoot><tr><th>Tổng điểm</th><td></td><th id="sa"></th><th id="sb"></th><th id="sc"></th></tr></tfoot></table></div><div id="supplier-result" class="feedback"></div><div class="buttons"><button class="btn" id="supplier-reset">Khôi phục số liệu slide</button><a class="btn" href="#source/slide/287">Đối chiếu nguồn</a></div></div><div class="callout warning"><strong>ĐIỂM CAO NHẤT CHƯA PHẢI KẾT LUẬN DUY NHẤT</strong>Cần kiểm tra các điều kiện kỹ thuật, pháp lý bắt buộc trước khi áp dụng điểm tổng. Một tiêu chí không đạt điều kiện bắt buộc không thể luôn được bù bởi điểm cao ở tiêu chí khác.</div>`;const calc=()=>{let w=[...document.querySelectorAll('.weight')].map(x=>+x.value),s=scores.map(r=>r.slice());document.querySelectorAll('.supplier-score').forEach(x=>s[+x.dataset.i][+x.dataset.j]=+x.value);if(w.some(x=>!Number.isFinite(x)||x<0||x>10)||s.flat().some(x=>x<1||x>5||!Number.isFinite(x))){$('#supplier-result').textContent='Nhập trọng số 0–10 và điểm 1–5 hợp lệ.';return}const totals=[0,1,2].map(j=>w.reduce((t,v,i)=>t+v*s[i][j],0));['#sa','#sb','#sc'].forEach((id,j)=>$(id).textContent=+totals[j].toFixed(2));const best=Math.max(...totals),win=totals.map((v,i)=>v===best?'ABC'[i]:null).filter(Boolean);$('#supplier-result').textContent=w.every(v=>v===0)?'Tất cả trọng số bằng 0: bảng chưa thể phân biệt các phương án.':`Nhà cung cấp ${win.join(', ')} ${win.length>1?'đồng hạng cao nhất':'có tổng điểm cao nhất'}: ${+best.toFixed(2)}. `+(w.join()==='4,5,1,2,3'&&JSON.stringify(s)===JSON.stringify(scores)?'Dữ liệu gốc: A=49, B=56, C=37.':'Đây là kết quả theo dữ liệu bạn vừa thay đổi.')};document.querySelectorAll('.weight,.supplier-score').forEach(x=>x.oninput=calc);$('#supplier-reset').onclick=supplier;calc()}
function perception(){$('#lab-content').innerHTML=`<div class="two-col"><div class="panel"><h2>Thay đổi tuyệt đối và tương đối</h2><p class="note">Minh họa hỗ trợ ý tưởng luật Weber ở slide 122. Chọn giá ban đầu và mức giảm, rồi so sánh tỷ lệ. Công cụ không dự đoán chắc chắn nhận thức của khách hàng.</p><label class="range-row">Giá ban đầu (đ)<input id="base" type="number" style="width:130px" min="1000" max="100000000" value="100000"></label><label class="range-row">Mức giảm (%)<input id="discount" type="range" min="0" max="50" value="10"><output id="discount-label"></output></label><div id="perception-result"></div></div><div class="panel"><h3>Thử hai trường hợp</h3><p>Giảm 10.000đ từ 50.000đ là 20%; giảm 10.000đ từ 5.000.000đ là 0,2%.</p><div class="callout"><strong>ĐIỂM CẦN GIẢI THÍCH</strong>Cùng độ thay đổi tuyệt đối nhưng kích thích nền khác nhau nên mức thay đổi tương đối khác nhau. Ngưỡng thực tế còn phụ thuộc người nhận, loại sản phẩm và bối cảnh.</div><p class="note">Không gán một tỷ lệ cố định là “ngưỡng nhận biết” cho mọi sản phẩm.</p></div></div>`;const update=()=>{const b=+$('#base').value,r=+$('#discount').value;$('#discount-label').textContent=r+'%';$('#perception-result').innerHTML=b>0&&Number.isFinite(b)?`<div class="metric">${(b*r/100).toLocaleString('vi-VN')}<span style="font-size:20px"> đ</span></div><p>Mức giảm tuyệt đối · Giá còn lại: <b>${(b*(1-r/100)).toLocaleString('vi-VN')}đ</b></p><div class="bar"><i style="width:${r*2}%"></i></div><p class="note">Tỷ lệ thay đổi ΔI / I = ${r/100}. Đây là phép tính tỷ lệ minh họa, không phải phép đo ngưỡng cá nhân.</p>`:'<p>Nhập giá ban đầu lớn hơn 0.</p>'};$('#base').oninput=update;$('#discount').oninput=update;update()}
const classifications=[['Bạn bè khuyên dùng một nhãn giày.','Xã hội','Nhóm tham khảo truyền thông tin và chuẩn mực.'],['Khách đang vội nên chọn điểm bán gần.','Tình huống','Áp lực thời gian và địa điểm làm thay đổi lựa chọn.'],['Người mua tin giá cao luôn đồng nghĩa chất lượng tốt.','Tâm lý','Niềm tin là một nội dung nhận thức.'],['Người có con nhỏ ưu tiên xe rộng, an toàn.','Cá nhân','Vòng đời gia đình làm thay đổi trách nhiệm và nhu cầu.'],['Tặng quà Tết để tri ân người lớn.','Văn hóa','Giá trị và phong tục định hướng ý nghĩa của món quà.'],['Khách thích khám phá, thường chọn hoạt động ngoài trời.','Cá nhân','Lối sống thể hiện qua cách phân bổ thời gian và hoạt động.'],['Mua hàng lặp lại vì lần trước rất hài lòng.','Tâm lý','Kết quả tích cực củng cố hành vi qua học hỏi.'],['Mua quà để dùng trong một buổi tiếp đối tác.','Tình huống','Nhiệm vụ và tình huống sử dụng định hình tiêu chí.'],['Doanh nghiệp bắt buộc có ba báo giá.','Tổ chức','Chính sách tổ chức quy định cách mua.'],['Trưởng bộ phận dùng uy tín thuyết phục hội đồng.','Tương tác cá nhân','Ảnh hưởng giữa các thành viên trong trung tâm mua.']];let classIndex=0;
function classify(){const d=classifications[classIndex%classifications.length];$('#lab-content').innerHTML=`<div class="panel"><span class="badge">Tình huống ${classIndex%classifications.length+1} / 10</span><h2 style="margin-top:18px">${d[0]}</h2><p class="note">Chọn yếu tố nổi bật nhất trong dữ kiện đã cho. Thực tế có thể chịu nhiều ảnh hưởng đồng thời.</p>${['Văn hóa','Xã hội','Cá nhân','Tâm lý','Tình huống','Tổ chức','Tương tác cá nhân'].map(x=>`<button class="option" data-class="${x}">${x}</button>`).join('')}<div id="class-feedback"></div><button class="btn primary" id="class-next">Tình huống tiếp theo →</button></div>`;document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{$('#class-feedback').innerHTML=`<div class="explanation"><strong>${b.dataset.class===d[1]?'✓ Chính xác':'Cần đối chiếu lại'} · ${d[1]}</strong><p>${d[2]}</p></div>`});$('#class-next').onclick=()=>{classIndex++;classify()}}
function source(c,n){let pool=n?slides.filter(s=>s.slide===n):c?slides.filter(s=>s.slide>=ranges[c-1][0]&&s.slide<=ranges[c-1][1]):slides;app.innerHTML=`<div class="eyebrow">TÀI LIỆU ĐỐI CHIẾU / 302 SLIDE</div><h1>Quay về đúng nguồn kiến thức.</h1><p class="intro">Văn bản, bảng và ảnh trích từ bài giảng của bạn. Các sơ đồ tạo bằng đối tượng PowerPoint không được tái tạo nguyên bố cục ở đây; tải file gốc để xem đầy đủ trình bày.</p><div class="buttons"><a class="btn primary" href="bai-giang-goc.pptx" download>Tải PowerPoint gốc ↓</a></div><div class="tabs"><button onclick="location.hash='source'">Tất cả</button>${chapterNames.map((_,i)=>`<button onclick="location.hash='source/${i+1}'" class="${c===i+1?'active':''}">Chương ${i+1}</button>`).join('')}</div><label for="slide-jump">Đến slide số </label><input id="slide-jump" type="number" min="1" max="302" value="${n||1}"> <button class="btn" id="jump-btn">Mở slide</button><p class="note">${pool.length} trang trong phạm vi đang xem. Bấm tiêu đề để mở.</p>${pool.map(sourceBlock).join('')}`;$('#jump-btn').onclick=()=>{const v=+$('#slide-jump').value;if(Number.isInteger(v)&&v>=1&&v<=302)location.hash='source/slide/'+v;else toast('Số slide cần từ 1 đến 302')};if(n)$('details').open=true}
function progress(){app.innerHTML=`<div class="eyebrow">TIẾN ĐỘ & GHI CHÚ</div><h1>Từng bài học tạo nên sự tiến bộ.</h1>${stats()}<div class="two-col"><div class="panel"><h2>Theo từng chương</h2>${chapterNames.map((n,i)=>{let ls=lessons.filter(l=>l.ch===i+1),d=ls.filter(l=>state.done.includes(l.id)).length;return `<div style="margin:24px 0"><a href="#chapter/${i+1}">${i+1}. ${n}</a><small style="float:right">${d}/${ls.length} bài</small><div class="bar"><i style="width:${d/ls.length*100}%"></i></div></div>`}).join('')}</div><div class="panel"><h2>Dữ liệu học tập</h2><p>${Object.values(state.notes).filter(Boolean).length} bài có ghi chú · ${Object.values(state.cases).filter(Boolean).length} tình huống có bài làm · ${state.wrong.length} câu đang cần ôn.</p><p class="note">Dữ liệu lưu trên trình duyệt, không đồng bộ giữa thiết bị. Xuất file để giữ lại ghi chú, câu sai và lịch sử.</p><div class="buttons"><button class="btn primary" id="export">Xuất tiến độ JSON</button><label class="btn" for="import">Nhập tiến độ</label><input type="file" id="import" accept="application/json" hidden></div>${btn('Ôn câu từng sai','#quiz')}</div></div><div class="panel"><h2>Lịch sử luyện tập</h2>${state.history.length?`<div class="table-wrap"><table><tr><th>Thời gian</th><th>Hình thức</th><th>Kết quả</th><th>Thời lượng</th></tr>${state.history.map(h=>`<tr><td>${esc(new Date(h.date).toLocaleString('vi-VN'))}</td><td>${h.mode==='learn'?'Luyện tập':'Tự kiểm tra'}</td><td>${h.correct}/${h.total} (${Math.round(h.correct/h.total*100)}%)</td><td>${Math.round(h.seconds/60)} phút</td></tr>`).join('')}</table></div>`:'<p class="muted">Chưa có phiên luyện. Hoàn thành một bài trắc nghiệm để bắt đầu ghi nhận.</p>'}</div>`;$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='tien-do-hanh-vi-khach-hang.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const d=JSON.parse(await f.text());if(!Array.isArray(d.done)||!Array.isArray(d.history)||!d.notes||!d.cases||!Array.isArray(d.wrong))throw Error('format');state={done:d.done.filter(x=>Number.isInteger(x)&&x>=0&&x<37),history:d.history.filter(h=>typeof h.date==='string'&&Number.isFinite(h.correct)&&h.correct>=0&&h.correct<=h.total&&Number.isFinite(h.total)&&h.total>0&&Number.isFinite(h.seconds)&&h.seconds>=0).slice(0,40),notes:Object.fromEntries(Object.entries(d.notes).filter(([k,v])=>+k>=0&&+k<37&&typeof v==='string')),cases:Object.fromEntries(Object.entries(d.cases).filter(([k,v])=>+k>=1&&+k<=7&&typeof v==='string')),wrong:d.wrong.filter(x=>Number.isInteger(x)&&x>=0&&x<42)};save();progress();toast('Đã nhập tiến độ')}catch{toast('File không đúng định dạng tiến độ của website')}}}
function search(term){const t=term.toLocaleLowerCase('vi-VN').normalize('NFD').replace(/\p{Diacritic}/gu,'').replace(/đ/g,'d');const match=s=>s.toLocaleLowerCase('vi-VN').normalize('NFD').replace(/\p{Diacritic}/gu,'').replace(/đ/g,'d').includes(t);const ls=lessons.filter(l=>match(l.title+' '+l.core.join(' '))),ss=slides.filter(s=>match(s.text+' '+JSON.stringify(s.tables)));app.innerHTML=`<div class="eyebrow">TRA CỨU HỌC PHẦN</div><h1>Tìm “${esc(term)}”</h1><p class="muted">${ls.length} bài học · ${ss.length} slide phù hợp. Hỗ trợ tìm không dấu.</p><h2>Bài học</h2><div class="result-list">${ls.map(l=>`<a href="#lesson/${l.id}"><span class="badge">Chương ${l.ch}</span><h3>${esc(l.title)}</h3><small>Slide ${l.start}–${l.end}</small></a>`).join('')||'<p>Không có bài phù hợp.</p>'}</div><h2 style="margin-top:30px">Slide gốc</h2><div class="result-list">${ss.map(s=>`<a href="#source/slide/${s.slide}"><span class="badge">Slide ${s.slide}</span><p>${esc(s.text.slice(0,210))}</p></a>`).join('')||'<p>Không có slide phù hợp.</p>'}</div>`}
function navigate(){const path=location.hash.slice(1).split('/'),[page,a,b]=path;$('#sidebar').classList.remove('open');document.querySelectorAll('nav a').forEach(x=>x.classList.toggle('active',x.getAttribute('href')==='#'+(page==='chapter'?'chapter/'+a:page||'home')));$('#crumb').textContent=({home:'Không gian học tập',chapter:'Lộ trình / Chương '+a,lesson:'Bài học tương tác',quiz:'Luyện tập & tự kiểm tra',labs:'Phòng thực hành',cases:'Tình huống vận dụng',flash:'Ôn nhớ bằng flashcard',source:'Tài liệu gốc',progress:'Tiến độ của bạn',search:'Tìm kiếm'})[page||'home']||'Không gian học tập';if(page==='chapter'&&+a>=1&&+a<=7)chapter(+a);else if(page==='lesson'&&Number.isInteger(+a)&&lessons[+a])lesson(+a);else if(page==='quiz')quiz(+a);else if(page==='flash')flash();else if(page==='cases'&&(!a||(+a>=1&&+a<=7)))cases(+a);else if(page==='labs')labs(a);else if(page==='source'){if(a==='slide'&&+b>=1&&+b<=302)source(0,+b);else source(+a>=1&&+a<=7?+a:0)}else if(page==='progress')progress();else if(page==='search'){try{search(decodeURIComponent(a||''))}catch{home()}}else home();window.scrollTo(0,0)}
$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');let searchTimer;$('#search').oninput=e=>{clearTimeout(searchTimer);const t=e.target.value.trim();if(t)searchTimer=setTimeout(()=>location.hash='search/'+encodeURIComponent(t),350)};
Promise.all(['lessons.json','slides.json','quiz.json'].map(u=>fetch(u).then(r=>{if(!r.ok)throw Error('load');return r.json()}))).then(([l,s,q])=>{lessons=l.map((x,i)=>({...x,id:i}));slides=s;questions=q;$('#mainnav').innerHTML=[['home','⌂','Tổng quan'],['quiz','✓','Luyện tập & kiểm tra'],['labs','◇','Phòng thực hành'],['cases','▧','Tình huống vận dụng'],['flash','▱','Flashcard'],['source','▤','Slide bài giảng'],['progress','◷','Tiến độ của tôi']].map(([p,i,t])=>`<a href="#${p}"><span class="nav-icon">${i}</span>${t}</a>`).join('');$('#chapternav').innerHTML=chapterNames.map((n,i)=>`<a href="#chapter/${i+1}"><span class="ch-num">${i+1}</span>${n}</a>`).join('');window.addEventListener('hashchange',navigate);navigate()}).catch(()=>{app.innerHTML='<div class="panel"><h1>Chưa tải được nội dung học.</h1><p>Kiểm tra kết nối rồi tải lại trang.</p><button class="btn" onclick="location.reload()">Tải lại</button></div>'});
